class Solution {
    public int rectangleArea(int[][] rectangles){
        long mod=1000000007L,area=0;
        TreeSet<Integer> xSet=new TreeSet<>();
        for(int[] rectangle:rectangles){
            xSet.add(rectangle[0]);
            xSet.add(rectangle[2]);
        }
        List<Integer> xs=new ArrayList<>(xSet);
        for(int i=0;i+1<xs.size();i++){
            int left=xs.get(i),right=xs.get(i+1);
            List<int[]> intervals=new ArrayList<>();
            for(int[] rectangle:rectangles)if(rectangle[0]<=left&&rectangle[2]>=right)intervals.add(new int[]{
                rectangle[1],rectangle[3]
            });
            intervals.sort(Comparator.comparingInt(a->a[0]));
            long covered=0;
            int start=0,end=0;
            boolean active=false;
            for(int[] interval:intervals){
                if(!active){
                    start=interval[0];
                    end=interval[1];
                    active=true;
                }else if(interval[0]>end){
                    covered+=end-start;
                    start=interval[0];
                    end=interval[1];
                }else end=Math.max(end,interval[1]);
            }
            if(active)covered+=end-start;
            area=(area+(long)(right-left)*covered)%mod;
        }
        return(int)area;
    }
}

