class Solution {
    fun rectangleArea(rectangles:Array<IntArray>):Int{
        val mod=1000000007L;
        var area=0L;
        val xs=rectangles.flatMap{
            listOf(it[0],it[2])
        }.distinct().sorted();
        for(i in 0 until xs.size-1){
            val left=xs[i];
            val right=xs[i+1];
            val intervals=rectangles.filter{
                it[0]<=left&&it[2]>=right
            }.map{
                intArrayOf(it[1],it[3])
            }.sortedBy{
                it[0]
            };
            var covered=0L;
            var start=0;
            var end=0;
            var active=false;
            for(interval in intervals){
                if(!active){
                    start=interval[0];
                    end=interval[1];
                    active=true
                }else if(interval[0]>end){
                    covered+=end-start;
                    start=interval[0];
                    end=interval[1]
                }else end=maxOf(end,interval[1])
            };
            if(active)covered+=end-start;
            area=(area+(right-left).toLong()*covered)%mod
        };
        return area.toInt()
    }
}

